window.__finlexDocLoaded(10194,{"id":10194,"articles":[{"id":1000807,"no":"Overview","heading":"Scope & Core Objective (Public Summary)","text":"Establishes computation and presentation of Basic and Diluted EPS for public entities, including the two-class method for participating securities, treasury stock method, and if-converted method.","seq":0},{"id":1000808,"no":"ASC 260-10","heading":"Basic/Diluted EPS, Two-Class & If-Converted Methods","text":"• Treasury Stock Method (ASC 260-10-45-23): Applied to options and warrants; assumed proceeds include unrecognized compensation cost for share-based awards.\n• Convertible Instruments (ASU 2020-06): Eliminates the treasury stock method for convertible debt settled in cash/shares, requiring the 'if-converted' method (with interest add-back and full share dilution unless principal must be settled in cash).\n• Two-Class Method (ASC 260-10-45-60): Mandatory when participating securities (e.g., unvested RSAs with nonforfeitable dividends) exist.","seq":1},{"id":1000809,"no":"US GAAP vs. IFRS / CAS","heading":"Key Cross-Framework Differences","text":"• Year-to-date Diluted EPS: ASC 260 averages incremental shares from each interim period, whereas IAS 33 computes YTD diluted EPS independently on a cumulative YTD basis (can yield different results when stock prices fluctuate).","seq":2},{"id":1000810,"no":"Official Access","heading":"Official FASB Codification & Reference Entry","text":"Official Portal (FASB Accounting Standards Codification®): https://asc.fasb.org/\nStatus: in_force (FASB ASC free Basic View available at https://asc.fasb.org/).","seq":3}]});
